INSERT INTO categories (slug, name, description) VALUES
  ('audio', 'Audio', 'Casques, enceintes et écouteurs pour écouter chez soi ou en déplacement.'),
  ('mobilite', 'Mobilité', 'Chargeurs, batteries et accessoires qui suivent le rythme de la journée.'),
  ('maison', 'Maison', 'Lumière, table et textile pour rendre les espaces plus agréables.'),
  ('bureau', 'Bureau', 'Carnets, stylos et rangements simples pour travailler sans distraction.')
INSERT INTO products (slug, name, category, price, summary, description, details, image, image_alt, stock, featured, badge) VALUES
  ('casque-studio-kola', 'Casque studio Kola', 'audio', 45000, 'Un casque fermé pour écouter et travailler sans être dérangé.', 'Le Kola isole correctement du bruit ambiant sans serrer la tête. Les coussinets se remplacent et l''arceau se range à plat dans la housse fournie.', ARRAY['Transducteurs de 40 mm','Bluetooth 5.3 et prise jack 3,5 mm','Autonomie annoncée de 38 heures','Poids de 265 g'], 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=80', 'Casque audio fermé posé sur un fond beige', 12, TRUE, 'Sélection'),
  ('enceinte-nomade-bassa', 'Enceinte nomade Bassa', 'audio', 32500, 'Une enceinte compacte, pensée pour la maison et les déplacements.', 'La Bassa tient dans un sac et diffuse un son équilibré dans une pièce moyenne. La dragonne en tissu permet de l''accrocher ou de la porter facilement.', ARRAY['Puissance de 20 W','Bluetooth 5.2','Autonomie annoncée de 16 heures','Résistance aux éclaboussures IPX5'], 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?auto=format&fit=crop&w=900&q=80', 'Enceinte portable rectangulaire avec sa dragonne', 8, TRUE, NULL),
  ('ecouteurs-fil-wouri', 'Écouteurs Fil Wouri', 'audio', 18000, 'Des écouteurs légers pour les trajets quotidiens.', 'Le format intra-auriculaire reste discret et stable. Le boîtier de charge ajoute deux recharges complètes et se glisse dans une poche.', ARRAY['Bluetooth 5.3','Autonomie de 6 heures par charge','Boîtier de charge USB-C','Trois tailles d''embouts fournies'], 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=900&q=80', 'Écouteurs sans fil et leur boîtier de charge', 20, FALSE, NULL),
  ('chargeur-rapide-65w', 'Chargeur rapide 65 W', 'mobilite', 15000, 'Un seul bloc pour l''ordinateur, la tablette et le téléphone.', 'Le chargeur propose deux ports USB-C et un port USB-A. La charge se répartit automatiquement selon les appareils branchés.', ARRAY['65 W sur le port USB-C principal','Deux ports USB-C et un port USB-A','Protection contre les surtensions','Câble USB-C de 1,5 m inclus'], 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?auto=format&fit=crop&w=900&q=80', 'Chargeur secteur compact avec deux ports USB-C', 16, FALSE, NULL),
  ('batterie-externe-20000', 'Batterie externe 20 000 mAh', 'mobilite', 24000, 'De quoi recharger un téléphone plusieurs fois pendant un déplacement.', 'La batterie affiche le niveau restant sur une petite rangée de diodes. Elle accepte la charge rapide en entrée comme en sortie.', ARRAY['Capacité de 20 000 mAh','Charge rapide 22,5 W','Deux sorties USB-A et une sortie USB-C','Poids de 410 g'], 'https://images.unsplash.com/photo-1609091839311-d5365f9ff1c5?auto=format&fit=crop&w=900&q=80', 'Batterie externe avec indicateurs de charge', 9, FALSE, NULL),
  ('support-telephone-bois', 'Support téléphone en bois', 'mobilite', 9500, 'Un support stable pour poser le téléphone pendant la journée.', 'Taillé dans du bois clair, le support accueille le téléphone en portrait comme en paysage. La rainure centrale laisse passer le câble de charge.', ARRAY['Bois d''hévéa huilé','Compatible avec la plupart des téléphones','Rainure pour le câble de charge','Fabrication locale'], 'https://images.unsplash.com/photo-1583394838336-acd977736f90?auto=format&fit=crop&w=900&q=80', 'Support en bois avec un téléphone posé dessus', 14, FALSE, NULL),
  ('lampe-bureau-mungo', 'Lampe de bureau Mungo', 'maison', 21000, 'Une lumière chaude et dirigée pour travailler le soir.', 'Le bras orientable place la lumière là où elle est utile. Le variateur à molette permet de passer d''une lumière douce à une lumière plus franche.', ARRAY['LED de 6 W, lumière chaude','Bras orientable en métal','Variateur d''intensité','Prise USB pour recharger un téléphone'], 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=900&q=80', 'Lampe de bureau à bras orientable', 7, TRUE, NULL),
  ('carafe-filtre-sanaga', 'Carafe filtre Sanaga', 'maison', 14500, 'Une carafe en verre pour garder de l''eau fraîche sur la table.', 'La carafe contient un litre et se ferme avec un couvercle en liège. Le filtre amovible retient les morceaux de fruits ou de menthe.', ARRAY['Verre borosilicate, 1 litre','Couvercle en liège','Filtre amovible en inox','Compatible avec le lave-vaisselle'], 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=900&q=80', 'Carafe en verre avec un couvercle en liège', 11, FALSE, NULL),
  ('plaid-coton-dibamba', 'Plaid coton Dibamba', 'maison', 27000, 'Un plaid léger en coton tissé pour les soirées plus fraîches.', 'Le tissage serré garde le plaid souple après lavage. Les rayures discrètes s''accordent avec un canapé clair comme avec un lit en bois.', ARRAY['100 % coton','Dimensions de 130 x 180 cm','Tissage local','Lavage à 30 degrés'], 'https://images.unsplash.com/photo-1584100936595-c0654b55a2e2?auto=format&fit=crop&w=900&q=80', 'Plaid en coton plié avec des rayures fines', 6, FALSE, NULL),
  ('carnet-relie-nyong', 'Carnet relié Nyong', 'bureau', 7500, 'Un carnet solide pour les notes et les listes du quotidien.', 'Les pages ivoire acceptent le stylo plume sans transpercer. La reliure cousue permet d''ouvrir le carnet bien à plat.', ARRAY['192 pages lignées','Papier 90 g/m²','Reliure cousue','Couverture en carton recyclé'], 'https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?auto=format&fit=crop&w=900&q=80', 'Carnet relié fermé avec un élastique', 24, TRUE, NULL),
  ('stylo-laiton-benoue', 'Stylo laiton Bénoué', 'bureau', 12000, 'Un stylo à bille simple, en laiton brossé.', 'Le corps en laiton prend une patine avec le temps. La recharge standard se remplace en dévissant la partie basse du stylo.', ARRAY['Corps en laiton brossé','Recharge à bille standard','Poids de 32 g','Livré dans un étui en carton'], 'https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?auto=format&fit=crop&w=900&q=80', 'Stylo en laiton posé en diagonale', 18, FALSE, NULL),
  ('organisateur-bureau-waza', 'Organisateur de bureau Waza', 'bureau', 16500, 'Un plateau en bois pour ranger stylos, carnet et petits objets.', 'Trois compartiments de tailles différentes gardent le bureau lisible. Le plateau se déplace facilement pour nettoyer dessous.', ARRAY['Bois de hévéa huilé','Trois compartiments','Dimensions de 28 x 18 cm','Fabrication locale'], 'https://images.unsplash.com/photo-1583485088034-697b5bc54ccd?auto=format&fit=crop&w=900&q=80', 'Organisateur de bureau en bois avec trois compartiments', 10, FALSE, NULL)
